fun openUrl(url: String) {
    window.open(url, "_blank")
}

// ---------------------------------------------------------------- stílusok
object GranitStyles : StyleSheet() {
    val cell by style {
        cursor("pointer")
        property("transition", "background-color 120ms")
        self + hover style {
            backgroundColor(rgba(0, 0, 0, 0.08))
        }
    }
    val button by style {
        cursor("pointer")
        property("border", "none")
        self + hover style {
            property("filter", "brightness(1.15)")
        }
    }
}

// ---------------------------------------------------------------- segédek
@JsName("ResizeObserver")
external class SizeObserver(callback: (dynamic, dynamic) -> Unit) {
    fun observe(target: Element)
    fun disconnect()
}

fun observeSize(el: Element, onResize: () -> Unit): SizeObserver {
    val o = SizeObserver { _, _ -> onResize() }
    o.observe(el)
    return o
}

/** Inline SVG beszúrása nyers szövegként (nem kell hozzá külön svg függőség). */
@Composable
fun RawSvg(html: String, attrs: AttrsScope<HTMLDivElement>.() -> Unit = {}) {
    key(html) {
        Div(attrs = {
            attrs()
            ref { it.innerHTML = html; onDispose { } }
        })
    }
}

/**
 * A szülőjét kitöltő canvas, ami méretváltozáskor (és kulcsváltozáskor) újrarajzol.
 * A `draw` CSS-pixelben kapja a méretet; a DPR-skálázás itt történik.
 */
@Composable
fun CanvasLayer(
    vararg keys: Any?,
    draw: (ctx: CanvasRenderingContext2D, w: Double, h: Double) -> Unit
) {
    key(CanvasLayerKey(keys)) {
        Canvas(attrs = {
            style {
                position(Position.Absolute)
                top(0.px); left(0.px)
                width(100.percent); height(100.percent)
                property("pointer-events", "none")
            }
            ref { canvas: HTMLCanvasElement ->
                fun redraw() {
                    val dpr = window.devicePixelRatio
                    val w = canvas.clientWidth.toDouble()
                    val h = canvas.clientHeight.toDouble()
                    if (w <= 0 || h <= 0) return
                    canvas.width = (w * dpr).toInt()
                    canvas.height = (h * dpr).toInt()
                    val ctx = canvas.getContext("2d") as CanvasRenderingContext2D
                    ctx.setTransform(dpr, 0.0, 0.0, dpr, 0.0, 0.0)
                    draw(ctx, w, h)
                }
                redraw()
                val obs = observeSize(canvas) { redraw() }
                onDispose { obs.disconnect() }
            }
        })
    }
}

private class CanvasLayerKey(
    private val keys: List<Any?>
) {
    override fun equals(other: Any?): Boolean =
        other is CanvasLayerKey && keys == other.keys

    override fun hashCode(): Int =
        keys.hashCode()

    constructor(vararg keys: Any?): this(
        keys = keys.toList()
    )
}