// =============================================================== Nyilak
private var arrowCounter = 0

/**
 * AnimatedUpArrow / AnimatedDownArrow egyben. A fénycsík egy animált
 * linearGradient (SMIL), amit csak a nyíl alakjára festünk.
 */
@Composable
fun AnimatedArrow(
    up: Boolean,
    widthPx: Int,
    heightPx: Int,
    baseColor: String = if (up) "#FF0000" else AppColors.ARROW_COLOR,
    glowColor: String = if (up) "#FF66A1" else AppColors.ARROW_GLOW_COLOR
) {
    val svg = remember(up, baseColor, glowColor) {
        val id = "arrowGlow${arrowCounter++}"
        fun y(v: Int) = if (up) v else 24 - v
        val d = "M8 ${y(21)} L8 ${y(15)} L3 ${y(15)} L12 ${y(4)} " +
                "L21 ${y(15)} L16 ${y(15)} L16 ${y(21)} Z"

        // top = 0.15*24, bottom = 0.85*24, glowHeight = 0.33*24, 1600 ms, lineáris
        // felfelé: progress -0.2 -> 1.2, lefelé: 1.2 -> -0.2
        val (y1, y2) = if (up) "31.68;8.16" to "15.84;-7.68"
        else "8.16;31.68" to "-7.68;15.84"

        """
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"
             preserveAspectRatio="none" width="100%" height="100%">
          <defs>
            <linearGradient id="$id" gradientUnits="userSpaceOnUse" x1="0" x2="0" y1="${y1.substringBefore(';')}" y2="${y2.substringBefore(';')}">
              <stop offset="0"    stop-color="$glowColor" stop-opacity="0"/>
              <stop offset="0.25" stop-color="$glowColor" stop-opacity="0.15"/>
              <stop offset="0.5"  stop-color="$glowColor" stop-opacity="1"/>
              <stop offset="0.75" stop-color="$glowColor" stop-opacity="0.15"/>
              <stop offset="1"    stop-color="$glowColor" stop-opacity="0"/>
              <animate attributeName="y1" values="$y1" dur="1.6s" repeatCount="indefinite"/>
              <animate attributeName="y2" values="$y2" dur="1.6s" repeatCount="indefinite"/>
            </linearGradient>
          </defs>
          <path d="$d" fill="$baseColor"/>
          <path d="$d" fill="url(#$id)"/>
        </svg>
        """.trimIndent()
    }
    RawSvg(svg, attrs = {
        style {
            width(widthPx.px); height(heightPx.px)
            property("flex", "none")
        }
    })
}

// =============================================================== Hóesés
private class Flake(
    var x: Double, var y: Double,
    val sizeDp: Double, val speed: Double,
    val swayDp: Double, val swayFreq: Double, val phase: Double,
    var rotation: Double, val rotSpeed: Double,
    val alpha: Double, val type: Int
)

private fun newFlake(startAnywhere: Boolean): Flake {
    val depth = Random.nextDouble()
    return Flake(
        x = Random.nextDouble(),
        y = if (startAnywhere) Random.nextDouble() else -0.05,
        sizeDp = 3.0 + depth * 7.0,
        speed = 0.06 + depth * 0.10,
        swayDp = 8.0 + Random.nextDouble() * 16.0,
        swayFreq = 0.5 + Random.nextDouble(),
        phase = Random.nextDouble() * 6.28,
        rotation = Random.nextDouble() * 360.0,
        rotSpeed = (Random.nextDouble() - 0.5) * 60.0,
        alpha = 0.55 + depth * 0.45,
        type = Random.nextInt(3)
    )
}

/** Teljes képernyős, kattintásátengedő hóesés. */
@Composable
fun SnowFall(flakeCount: Int) {
    key(flakeCount) {
        Canvas(attrs = {
            style {
                position(Position.Fixed)
                top(0.px); left(0.px)
                width(100.percent); height(100.percent)
                property("pointer-events", "none")
                property("z-index", 0)
            }
            ref { canvas: HTMLCanvasElement ->
                val flakes = List(flakeCount) { newFlake(true) }
                var last = 0.0
                var handle = 0

                fun frame(now: Double) {
                    val dpr = window.devicePixelRatio
                    val w = canvas.clientWidth.toDouble()
                    val h = canvas.clientHeight.toDouble()
                    val pw = (w * dpr).toInt()
                    val ph = (h * dpr).toInt()
                    if (canvas.width != pw || canvas.height != ph) {
                        canvas.width = pw; canvas.height = ph
                    }
                    val ctx = canvas.getContext("2d") as CanvasRenderingContext2D
                    ctx.setTransform(dpr, 0.0, 0.0, dpr, 0.0, 0.0)
                    ctx.clearRect(0.0, 0.0, w, h)

                    val dt = if (last == 0.0) 0.0 else (now - last) / 1000.0
                    last = now
                    val t = now / 1000.0

                    for (f in flakes) {
                        f.y += f.speed * dt
                        f.rotation += f.rotSpeed * dt
                        if (f.y > 1.05) {
                            val n = newFlake(false)
                            f.x = n.x; f.y = n.y
                        }
                        val sway = sin(t * f.swayFreq + f.phase) * f.swayDp
                        val cx = f.x * w + sway
                        val cy = f.y * h
                        val radius = f.sizeDp
                        drawSnowflake(
                            ctx, cx, cy, radius, f.rotation, f.type,
                            "rgba(255,255,255,${f.alpha})",
                            (radius * 0.14).coerceAtLeast(1.0)
                        )
                    }
                    handle = window.requestAnimationFrame { frame(it) }
                }
                handle = window.requestAnimationFrame { frame(it) }
                onDispose { window.cancelAnimationFrame(handle) }
            }
        })
    }
}

private fun CanvasRenderingContext2D.seg(x1: Double, y1: Double, x2: Double, y2: Double) {
    beginPath(); moveTo(x1, y1); lineTo(x2, y2); stroke()
}

private fun drawSnowflake(
    ctx: CanvasRenderingContext2D,
    cx: Double, cy: Double, radius: Double,
    rotationDeg: Double, type: Int, color: String, stroke: Double
) {
    ctx.strokeStyle = color
    ctx.fillStyle = color
    ctx.lineWidth = stroke
    ctx.asDynamic().lineCap = "round"

    for (i in 0 until 6) {
        val armAngle = (rotationDeg + i * 60.0 - 90.0) * PI / 180.0
        val dx = cos(armAngle)
        val dy = sin(armAngle)

        ctx.lineWidth = stroke
        ctx.seg(cx, cy, cx + dx * radius, cy + dy * radius)

        fun branch(at: Double, len: Double, spread: Double = 40.0) {
            val bx = cx + dx * radius * at
            val by = cy + dy * radius * at
            ctx.lineWidth = stroke * 0.85
            for (s in intArrayOf(-1, 1)) {
                val a = armAngle + spread * s * PI / 180.0
                ctx.seg(bx, by, bx + cos(a) * radius * len, by + sin(a) * radius * len)
            }
        }

        when (type) {
            0 -> branch(0.55, 0.35)
            1 -> { branch(0.4, 0.28); branch(0.7, 0.22) }
            else -> { branch(0.35, 0.3, 55.0); branch(0.65, 0.3, 35.0) }
        }
    }
    ctx.beginPath()
    ctx.arc(cx, cy, stroke * 1.1, 0.0, 2 * PI, false)
    ctx.fill()
}
