// =============================================================== RichText (AnnotatedString helyett)
sealed interface RichPart {
    data class Plain(val text: String) : RichPart
    data class Link(
        val text: String,
        val onClick: () -> Unit,
        val bold: Boolean = false,
        val fontSize: Int? = null,
        val color: CSSColorValue? = null
    ) : RichPart
}

typealias RichText = List<RichPart>

@Composable
fun RichTextView(parts: RichText) {
    parts.forEach { p ->
        when (p) {
            is RichPart.Plain -> Text(p.text)
            is RichPart.Link -> Span(attrs = {
                onClick { p.onClick() }
                style {
                    cursor("pointer")
                    property("text-decoration", "underline")
                    if (p.bold) fontWeight("bold")
                    p.fontSize?.let { fontSize(it.px) }
                    p.color?.let { color(it) }
                }
            }) { Text(p.text) }
        }
    }
}

data class CardContent(val subTitle: Boolean, val content: RichText) {
    constructor(subTitle: Boolean, content: String) : this(subTitle, listOf(RichPart.Plain(content)))
}

// =============================================================== RequirementCard.kt
private val darkGray = Color("#444444")

/** TranslucentShadowCard: a CSS box-shadow eleve csak a doboz kívül látszik, így nincs kivágás. */
@Composable
fun TranslucentShadowCard(
    color: String = "rgba(0,255,0,0.4)",
    extraStyle: StyleScope.() -> Unit = {},
    content: @Composable () -> Unit
) {
    Div(attrs = {
        style {
            width(100.percent)
            property("box-sizing", "border-box")
            borderRadius(12.px)
            property("box-shadow", "0 6px 24px rgba(0,0,0,0.45)")
            property("background-color", color)
            extraStyle()
        }
    }) { content() }
}

@Composable
fun ContentCard(title: String, content: List<CardContent>) {
    TranslucentShadowCard(color = "rgba(255,255,255,0.4)") {
        Div(attrs = {
            style {
                padding(8.px, 8.px, 20.px, 8.px)
                color(darkGray)
                fontSize(16.px)
                property("white-space", "pre-wrap")
                property("user-select", "text")
            }
        }) {
            Div(attrs = {
                style {
                    fontSize(18.px); fontWeight("bold")
                    padding(8.px, 0.px, 8.px, 4.px)
                }
            }) { Text(title) }

            content.forEach {
                if (it.subTitle) {
                    Div(attrs = {
                        style {
                            fontWeight("bold"); fontSize(16.px)
                            padding(6.px, 4.px, 0.px, 4.px)
                        }
                    }) { RichTextView(it.content) }
                } else {
                    Div { Text(" • "); RichTextView(it.content) }
                }
            }
        }
    }
}

