// =============================================================== How: PhoneBox
@Composable
fun PhoneBox(content: @Composable () -> Unit) {
    var dims by remember { mutableStateOf<Pair<Double, Double>?>(null) }
    val (iw, ih) = dims ?: (1.0 to 1.0)
    val ratio = iw / ih

    Div(attrs = {
        style {
            position(Position.Relative)
            property("z-index", 1)
            property("flex", "0 1 auto")
            // widthIn(max = 300) + heightIn(max = 650) + aspectRatio
            property("width", "min(100%, 300px, ${650 * ratio}px)")
            property("aspect-ratio", "$ratio")
        }
    }) {
        Img(src = "phone.webp", attrs = {
            style {
                width(100.percent); height(100.percent)
                property("display", "block")
                property("object-fit", "fill")
            }
            ref { img: HTMLImageElement ->
                fun read() {
                    if (img.naturalWidth > 0) dims = img.naturalWidth.toDouble() to img.naturalHeight.toDouble()
                }
                read()
                img.addEventListener("load", { read() })
                onDispose { }
            }
        })

        if (dims != null) {
            Div(attrs = {
                style {
                    position(Position.Absolute)
                    left((23 / iw * 100).percent)
                    top((106 / ih * 100).percent)
                    width((467 / iw * 100).percent)
                    height((790 / ih * 100).percent)
                    backgroundColor(rgba(0, 0, 255, 0.4))
                    property("overflow", "hidden")
                }
            }) { content() }
        }
    }
}

// =============================================================== How: ConnectedFlowRow
@Composable
fun ConnectedFlowRow(items: List<@Composable () -> Unit>) {
    Div(attrs = {
        style {
            position(Position.Relative)
            width(100.percent)
            property("box-sizing", "border-box")
            padding(0.px, 16.px)
            display(DisplayStyle.Flex)
            property("flex-wrap", "wrap")
            justifyContent(JustifyContent.Center)
            gap(32.px)
        }
    }) {
        Canvas(attrs = {
            style {
                position(Position.Absolute)
                top(0.px); left(0.px)
                width(100.percent); height(100.percent)
                property("z-index", 0)
                property("pointer-events", "none")
            }
            ref { canvas: HTMLCanvasElement ->
                var handle = 0
                fun frame(now: Double) {
                    val parent = canvas.parentElement
                    if (parent != null) {
                        val dpr = window.devicePixelRatio
                        val w = canvas.clientWidth.toDouble()
                        val h = canvas.clientHeight.toDouble()
                        val pw = (w * dpr).toInt()
                        val ph = (h * dpr).toInt()
                        if (canvas.width != pw || canvas.height != ph) { canvas.width = pw; canvas.height = ph }
                        val ctx = canvas.getContext("2d") as CanvasRenderingContext2D
                        ctx.setTransform(dpr, 0.0, 0.0, dpr, 0.0, 0.0)
                        ctx.clearRect(0.0, 0.0, w, h)

                        val pr = parent.getBoundingClientRect()
                        val centers = (1 until parent.children.length).mapNotNull { i ->
                            parent.children.item(i)?.getBoundingClientRect()?.let {
                                (it.left - pr.left + it.width / 2) to (it.top - pr.top + it.height / 2)
                            }
                        }
                        val progress = (now % 1200.0) / 1200.0
                        ctx.asDynamic().lineCap = "round"

                        for (i in 0 until centers.size - 1) {
                            val (sx, sy) = centers[i]
                            val (ex, ey) = centers[i + 1]

                            ctx.strokeStyle = "#455A64"
                            ctx.lineWidth = 6.0
                            ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke()

                            val dx = ex - sx
                            val dy = ey - sy
                            val len = sqrt(dx * dx + dy * dy).coerceAtLeast(1.0)
                            val ux = dx / len
                            val uy = dy / len
                            val gcx = sx + dx * progress
                            val gcy = sy + dy * progress
                            val half = 40.0
                            val gx0 = gcx - ux * half; val gy0 = gcy - uy * half
                            val gx1 = gcx + ux * half; val gy1 = gcy + uy * half

                            val grad = ctx.createLinearGradient(gx0, gy0, gx1, gy1)
                            grad.addColorStop(0.0, "rgba(0,229,255,0)")
                            grad.addColorStop(0.5, "#00E5FF")
                            grad.addColorStop(1.0, "rgba(0,229,255,0)")
                            ctx.strokeStyle = grad
                            ctx.lineWidth = 10.0
                            ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx1, gy1); ctx.stroke()
                        }
                    }
                    handle = window.requestAnimationFrame { frame(it) }
                }
                handle = window.requestAnimationFrame { frame(it) }
                onDispose { window.cancelAnimationFrame(handle) }
            }
        })

        items.forEach { ui -> PhoneBox { ui() } }
    }
}

// =============================================================== How: lépések
/** A lépések közös váza: padding 8, felül ikonhely (a magasság 20%-a), alatta szöveg. */
@Composable
private fun StepLayout(
    icon: @Composable () -> Unit,
    body: @Composable () -> Unit
) {
    Div(attrs = {
        style {
            width(100.percent); height(100.percent)
            property("box-sizing", "border-box")
            padding(8.px)
            property("overflow-y", "auto")
            property("overflow-x", "hidden")
        }
    }) {
        Div(attrs = {
            style {
                position(Position.Relative)
                width(100.percent)
                height(20.percent)
            }
        }) { icon() }
        Div(attrs = {
            style {
                paddingTop(12.px)
                display(DisplayStyle.Flex)
                flexDirection(FlexDirection.Column)
                gap(12.px)
                property("user-select", "text")
                property("overflow-wrap", "anywhere")
                property("min-width", "0")
            }
        }) { body() }
    }
}

private fun StyleScope.bold18() {
    fontWeight("bold"); fontSize(18.px)
}

@Composable
fun FirstStep(viewModel: AppViewModel) {
    val code = remember { viewModel.inviteCodes.random() }
    val url = "https://granitbank.hu"

    StepLayout(
        icon = {
            RawSvg(PERSON_SVG, attrs = { style { width(100.percent); height(100.percent) } })
            // a Box(size(height)).border(1.dp, Gray) megfelelője: négyzet az ikon körül
            Div(attrs = {
                style {
                    position(Position.Absolute)
                    top(0.px); left(50.percent)
                    height(100.percent)
                    property("aspect-ratio", "1")
                    property("transform", "translateX(-50%)")
                    property("border", "1px solid gray")
                    property("box-sizing", "border-box")
                }
            })
        },
        body = {
            Div(attrs = { style { bold18() } }) { Text(viewModel.getText("step_1")) }

            Div(attrs = {
                onClick { viewModel.copyToClipboard(code) }
                style {
                    width(100.percent)
                    property("text-align", "center")
                    fontWeight("bold"); fontSize(24.px)
                    color(Color.black)
                    cursor("pointer")
                    textDecoration("underline")
                }
            }) { Text(code) }

            Div(attrs = { style { bold18() } }) {
                Text(viewModel.getText("step_1_1"))
                Span(attrs = {
                    onClick { openUrl(url) }
                    style { color(Color.black); cursor("pointer"); property("text-decoration", "underline") }
                }) { Text(url) }
            }
        }
    )
}

