// =============================================================== CloudGeometry
/** A felhő geometriája (a KMP-s CloudGeometry portja, Double-lel). */
internal class CloudGeometry(
    r: Double, w: Double, h: Double, withTail: Boolean = false
) {
    val pitch = r * 1.5
    val cr = pitch * 2.0
    val tailExtra = if (withTail) r * 1.6 else 0.0
    val bodyBottom = h - tailExtra

    val left = r
    val top = r
    val right = max(w - r, left + 1.0)
    val bottom = max(bodyBottom - r, top + 1.0)

    val nx = max(2, ((right - left - 2 * cr) / pitch).roundToInt())
    val ny = max(3, ((bottom - top - 2 * cr) / pitch).roundToInt())
    val px = max(right - left - 2 * cr, 2 * pitch) / nx
    val py = max(bottom - top - 2 * cr, 3 * pitch) / ny

    /** (x, y, sugár-szorzó) */
    fun bumps(cornerScale: Double): List<Triple<Double, Double, Double>> {
        val list = mutableListOf<Triple<Double, Double, Double>>()
        for (i in 0 until nx) {
            val x = left + cr + (i + 0.5) * px
            list += Triple(x, top, 1.0)
            list += Triple(x, bottom, 1.0)
        }
        for (i in 0 until ny) {
            val y = top + cr + (i + 0.5) * py
            list += Triple(left, y, 1.0)
            list += Triple(right, y, 1.0)
        }
        fun arc(cx: Double, cy: Double, startDeg: Double) {
            for (i in 0 until 3) {
                val a = (startDeg + 90.0 * (i + 0.5) / 3.0) * PI / 180.0
                list += Triple(
                    cx + cr * cos(a), cy + cr * sin(a),
                    if (i == 1) cornerScale else 1.0
                )
            }
        }
        arc(right - cr, top + cr, -90.0)
        arc(right - cr, bottom - cr, 0.0)
        arc(left + cr, bottom - cr, 90.0)
        arc(left + cr, top + cr, 180.0)
        return list
    }
}

// =============================================================== CloudShape
/**
 * Felhő-path: lekerekített téglalap + körök, mind azonos körüljárással,
 * így a nonzero kitöltés/clip az uniójukat adja.
 */
internal fun CanvasRenderingContext2D.cloudPath(
    g: CloudGeometry, r: Double, cornerScale: Double
) {
    beginPath()
    moveTo(g.left + g.cr, g.top)
    lineTo(g.right - g.cr, g.top)
    arc(g.right - g.cr, g.top + g.cr, g.cr, -PI / 2, 0.0, false)
    lineTo(g.right, g.bottom - g.cr)
    arc(g.right - g.cr, g.bottom - g.cr, g.cr, 0.0, PI / 2, false)
    lineTo(g.left + g.cr, g.bottom)
    arc(g.left + g.cr, g.bottom - g.cr, g.cr, PI / 2, PI, false)
    lineTo(g.left, g.top + g.cr)
    arc(g.left + g.cr, g.top + g.cr, g.cr, PI, PI * 1.5, false)
    closePath()
    for ((x, y, s) in g.bumps(cornerScale)) {
        val rr = r * s
        moveTo(x + rr, y)
        arc(x, y, rr, 0.0, 2 * PI, false)
    }
}

/** Ellipszis + egyenletes ívhossz-osztású bodrok (OvalCloudShape portja). */
internal fun CanvasRenderingContext2D.ovalCloudPath(w: Double, h: Double, bumpPx: Double) {
    val r = min(bumpPx, min(w, h) * 0.28).coerceAtLeast(1.0)
    val cx = w / 2
    val cy = h / 2
    val a = max(w / 2 - r, 1.0)
    val b = max(h / 2 - r, 1.0)

    val steps = 720
    val cum = DoubleArray(steps + 1)
    var px = a
    var py = 0.0
    for (i in 1..steps) {
        val t = 2.0 * PI * i / steps
        val x = a * cos(t)
        val y = b * sin(t)
        cum[i] = cum[i - 1] + sqrt((x - px) * (x - px) + (y - py) * (y - py))
        px = x; py = y
    }
    val total = cum[steps]
    val count = max(6, (total / (r * 1.5)).roundToInt())

    beginPath()
    moveTo(cx + a, cy)
    ellipse(cx, cy, a, b, 0.0, 0.0, 2 * PI, false)

    var idx = 0
    for (k in 0 until count) {
        val target = total * k / count
        while (idx < steps - 1 && cum[idx + 1] < target) idx++
        val seg = cum[idx + 1] - cum[idx]
        val frac = if (seg > 0) (target - cum[idx]) / seg else 0.0
        val t = 2.0 * PI * (idx + frac) / steps
        val x = cx + a * cos(t)
        val y = cy + b * sin(t)
        moveTo(x + r, y)
        arc(x, y, r, 0.0, 2 * PI, false)
    }
}

/** A már felépített path-t szegélyezi (kívülre) és kitölti. */
private fun CanvasRenderingContext2D.strokeThenFill(fill: String, line: String, bw: Double) {
    asDynamic().lineJoin = "round"
    lineWidth = bw * 2
    strokeStyle = line
    stroke()
    fillStyle = fill
    fill()
}

// =============================================================== Grid bubble
@Composable
fun CloudGridBubbleSixElement(
    viewModel: AppViewModel,
    leftItems: List<String>,
    rightItems: List<String>,
    bumpRadius: Double = 16.0,
    lineColor: String = AppColors.BUBBLE_LINE_COLOR,
    borderWidth: Double = 1.0,
    cellColors: List<String> = AppColors.codeBubbleColors
) = CloudGridBubble(viewModel, leftItems, rightItems, 3, bumpRadius, lineColor, borderWidth, cellColors)

@Composable
fun CloudGridBubbleFourElement(
    viewModel: AppViewModel,
    leftItems: List<String>,
    rightItems: List<String>,
    bumpRadius: Double = 16.0,
    lineColor: String = AppColors.BUBBLE_LINE_COLOR,
    borderWidth: Double = 1.0,
    cellColors: List<String> = AppColors.codeBubbleColors
) = CloudGridBubble(viewModel, leftItems, rightItems, 2, bumpRadius, lineColor, borderWidth, cellColors)

/** A szülő teljes területét kitölti (a KMP-s fillMaxSize megfelelője). */
@Composable
private fun CloudGridBubble(
    viewModel: AppViewModel,
    leftItems: List<String>,
    rightItems: List<String>,
    rows: Int,
    bumpRadius: Double,
    lineColor: String,
    borderWidth: Double,
    cellColors: List<String>
) {
    require(rows == 2 || rows == 3)

    Div(attrs = {
        style {
            position(Position.Relative)
            width(100.percent); height(100.percent)
            property("min-height", "${(72 * rows) + bumpRadius}px")
        }
    }) {
        CanvasLayer(
            rows,
            bumpRadius,
            lineColor,
            borderWidth,
            cellColors
        ) { ctx, w, h ->
            drawGrid(ctx, w, h, rows, bumpRadius, borderWidth, bumpRadius, lineColor, cellColors)
        }

        // tartalom: csak a farok helyét hagyjuk ki alul
        Div(attrs = {
            style {
                position(Position.Absolute)
                top(0.px); left(0.px); right(0.px); bottom(bumpRadius.px)
                display(DisplayStyle.Flex)
            }
        }) {
            listOf(leftItems, rightItems).forEach { items ->
                Div(attrs = {
                    style {
                        property("flex", "1 1 0")
                        display(DisplayStyle.Flex)
                        flexDirection(FlexDirection.Column)
                        property("min-width", "0")
                    }
                }) {
                    items.take(rows).forEach { Cell(it, viewModel) }
                }
            }
        }
    }
}

@Composable
private fun Cell(text: String, viewModel: AppViewModel) {
    Div(attrs = {
        classes(GranitStyles.cell)
        onClick { viewModel.copyToClipboard(text) }
        style {
            property("flex", "1 1 0")
            display(DisplayStyle.Flex)
            alignItems(AlignItems.Center)
            justifyContent(JustifyContent.Center)
            property("box-sizing", "border-box")
            margin(6.px, 8.px)
            borderRadius(32.px)
            padding(0.px, 8.px)
        }
    }) {
        Div(attrs = {
            style {
                color(Color(AppColors.CODE_TEXT_COLOR))
                fontWeight("bold")
                fontSize(26.px)
                property("text-align", "center")
                property("user-select", "text")
            }
        }) { Text(text) }
        RawSvg(COPY_SVG, attrs = {
            style {
                width(24.px); height(24.px)
                marginLeft(8.px)
                property("flex", "none")
                color(Color(AppColors.CODE_TEXT_COLOR))
            }
        })
    }
}

private const val COPY_SVG =
    """<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="M9 18q-.825 0-1.412-.587T7 16V4q0-.825.588-1.412T9 2h9q.825 0 1.413.588T20 4v12q0 .825-.587 1.413T18 18zm0-2h9V4H9zm-4 6q-.825 0-1.412-.587T3 20V6h2v14h11v2zm4-6V4z"/></svg>"""

private typealias Pt = Pair<Double, Double>

private fun CanvasRenderingContext2D.poly(vararg parts: List<Pt>) {
    beginPath()
    var first = true
    for (p in parts) for ((x, y) in p) {
        if (first) { moveTo(x, y); first = false } else lineTo(x, y)
    }
    closePath()
}

private fun CanvasRenderingContext2D.line(pts: List<Pt>) {
    beginPath()
    pts.forEachIndexed { i, (x, y) -> if (i == 0) moveTo(x, y) else lineTo(x, y) }
}

private fun drawGrid(
    ctx: CanvasRenderingContext2D, canvasW: Double, canvasH: Double, rows: Int,
    r: Double, bw: Double, tail: Double, lineColor: String, cellColors: List<String>
) {
    val W = canvasW - 2 * bw
    val H = canvasH - 2 * bw
    ctx.save()
    ctx.translate(bw, bw)

    // alap + szegély
    val g = CloudGeometry(r, W, H)
    ctx.cloudPath(g, r, 1.3)
    ctx.strokeThenFill("#3300FFFF", lineColor, bw)

    val bodyH = H - tail
    val rowH = bodyH / rows
    val cx = W / 2
    val amp = r * 0.35
    val halfWave = r * 1.5
    val big = r * 4

    fun sampleY(f: (Double) -> Double): List<Pt> {
        val l = ArrayList<Pt>()
        var y = -big
        while (y <= H + big) { l += f(y) to y; y += 2.0 }
        return l
    }
    fun sampleX(f: (Double) -> Double): List<Pt> {
        val l = ArrayList<Pt>()
        var x = -big
        while (x <= W + big) { l += x to f(x); x += 2.0 }
        return l
    }

    // függőleges hullámvonal
    val m = if (rows == 3) {
        val n = ((bodyH / halfWave / 3.0 - 1.0) / 2.0).roundToInt().coerceAtLeast(0)
        3 * (2 * n + 1)
    } else {
        2 * (bodyH / halfWave / 2.0).roundToInt().coerceAtLeast(1)
    }
    val vertical = sampleY { y -> cx + amp * sin(PI * m * y / bodyH) }

    // vízszintes hullámvonalak (tükrözve váltakozó irányban)
    val lines = (0 until rows - 1).map { i ->
        val y0 = rowH * (i + 1)
        val dir = if (i % 2 == 0) 1.0 else -1.0
        sampleX { x -> y0 + dir * amp * sin(PI * (x - cx) / halfWave) }
    }

    val leftCorners = listOf(-big to H + big, -big to -big)
    val rightCorners = listOf(W + big to H + big, W + big to -big)

    fun band(i: Int): List<Pt> {
        val upper = if (i == 0) listOf(-big to -big, W + big to -big) else lines[i - 1]
        val lower = if (i == rows - 1) listOf(W + big to H + big, -big to H + big)
        else lines[i].reversed()
        return upper + lower
    }

    // cellák: bal oszlop fentről le, majd jobb oszlop
    var idx = 0
    for (side in listOf(leftCorners, rightCorners)) {
        for (b in 0 until rows) {
            ctx.save()
            ctx.cloudPath(g, r, 1.3); ctx.clip()
            ctx.poly(vertical, side); ctx.clip()
            ctx.poly(band(b)); ctx.clip()

            // a cellák kitöltésénél a drawGrid-ben
            ctx.fillStyle = "#3300FFFF"                                   // <-- ha a következő sor érvénytelen, ez marad
            ctx.fillStyle = cellColors.getOrElse(idx) { "#3300FFFF" }

            ctx.fillRect(-big, -big, W + 2 * big, H + 2 * big)
            ctx.fillRect(-big, -big, W + 2 * big, H + 2 * big)
            ctx.restore()
            idx++
        }
    }

    // vonalak a felhőn belül
    ctx.save()
    ctx.cloudPath(g, r, 1.3); ctx.clip()
    ctx.strokeStyle = lineColor
    ctx.lineWidth = bw
    ctx.asDynamic().lineCap = "round"
    ctx.asDynamic().lineJoin = "round"
    ctx.line(vertical); ctx.stroke()
    lines.forEach { ctx.line(it); ctx.stroke() }
    ctx.restore()

    ctx.restore()
}

// =============================================================== Oval bubble
@Composable
fun OvalCloudBubble(
    width: Int,
    height: Int,
    text: String? = null,           // null = üres buborék
    bumpRadius: Double = 12.0,
    fillColor: String = "#FFFFFF",
    lineColor: String = "#D3D3D3",
    borderWidth: Double = 1.0
) {
    Div(attrs = {
        style {
            position(Position.Relative)
            width(width.px); height(height.px)
            display(DisplayStyle.Flex)
            alignItems(AlignItems.Center)
            justifyContent(JustifyContent.Center)
            property("flex", "none")
            property("box-sizing", "border-box")
            if (text != null) padding(bumpRadius.px, (bumpRadius * 2).px)
        }
    }) {
        CanvasLayer(
            width,
            height,
            bumpRadius,
            fillColor,
            lineColor,
            borderWidth
        ) { ctx, w, h ->
            ctx.save()
            ctx.translate(borderWidth, borderWidth)
            ctx.ovalCloudPath(w - 2 * borderWidth, h - 2 * borderWidth, bumpRadius)
            ctx.strokeThenFill(fillColor, lineColor, borderWidth)
            ctx.fillStyle = "rgba(0,255,255,0.2)"
            ctx.fill()
            ctx.restore()
        }

        if (text != null) {
            Div(attrs = {
                style {
                    position(Position.Relative)
                    display(DisplayStyle.Flex)
                    alignItems(AlignItems.Center)
                }
            }) {
                AnimatedArrow(up = true, widthPx = 26, heightPx = 30)
                Div(attrs = {
                    style {
                        color(Color("#263238"))
                        fontWeight("bold")
                        fontSize(18.px)
                        property("text-align", "center")
                        property("white-space", "nowrap")
                        property("user-select", "text")
                        margin(6.px, 6.px)
                    }
                }) { Text(text) }
                AnimatedArrow(up = true, widthPx = 26, heightPx = 30)
            }
        }
    }
}
