import kotlinx.browser.window
import kotlinx.coroutines.await
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

suspend fun getAboutData(): LibrariesResponse {
    val string = window.fetch("aboutlibraries.json").await().text().await()
    val json = Json { ignoreUnknownKeys = true }
    return json.decodeFromString<LibrariesResponse>(string)
}

@Serializable
data class LibrariesResponse(val libraries: List<Library>, val licenses: Map<String, License>)

@Serializable
data class Library(
    val uniqueId: String,
    val funding: List<String> = emptyList(),
    val developers: List<Developer>,
    val artifactVersion: String,
    val description: String,
    val scm: Scm,
    val name: String,
    val website: String,
    val licenses: List<String>
)

@Serializable
data class Developer(val name: String, val organisationUrl: String? = null)

@Serializable
data class Scm(val connection: String? = null, val url: String, val developerConnection: String? = null)

@Serializable
data class License(
    val content: String, val hash: String, val internalHash: String,
    val url: String, val spdxId: String, val name: String
)