import androidx.compose.runtime.mutableStateMapOf
import kotlinx.browser.window
import kotlinx.coroutines.await
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.update
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.jetbrains.compose.web.css.rgb
import org.jetbrains.compose.web.css.rgba

class AppViewModel {

    val topButtons = mapOf(
        "button_1_text" to { showScreen(Screen.MAIN) },
        "button_2_text" to { showScreen(Screen.HOW) },
        "button_3_text" to { showScreen(Screen.REQUIREMENTS) }
    )

    val inviteCodes = listOf("DGCOT", "KCP1J", "FMUZV", "NTAVO")

    val appState: StateFlow<AppState> field = MutableStateFlow(AppState())

    private val texts = mutableStateMapOf<String, String>()

    fun showScreen(screen: Screen) {
        appState.update { it.copy(showedScreen = screen) }
    }

    fun showingCopied(showing: Boolean) {
        appState.update { it.copy(showingCopiedToast = showing) }
    }

    fun copyToClipboard(text: String) {
        window.navigator.asDynamic().clipboard.writeText(text)
        showingCopied(true)
    }

    private val codePlaceholder = "[code]"

    fun getWithUrlOrCode(
        template: String,
        replace: Map<String, String>,
        replaceUrl: Boolean = false
    ): RichText {
        val out = mutableListOf<RichPart>()
        var cur = 0
        replace.forEach { (placeholder, value) ->
            val index = template.indexOf(placeholder, cur)
            if (index == -1) return@forEach
            out += RichPart.Plain(template.substring(cur, index))
            if (placeholder != codePlaceholder) {
                out += RichPart.Link(if (replaceUrl) value else placeholder, { openUrl(value) }, color = rgb(103, 80, 164))
            } else {
                val code = inviteCodes.random()
                out += RichPart.Link(code, { copyToClipboard(code) }, bold = true, fontSize = 16, color = rgb(103, 80, 164))
            }
            cur = index + placeholder.length
        }
        out += RichPart.Plain(template.substring(cur))
        return out
    }

    suspend fun loadTexts() {
        val string = window.fetch("strings.json").await().text().await()
        val json = Json { ignoreUnknownKeys = true }
        val texts = json.decodeFromString<List<TextValue>>(string)

        texts.forEach { this.texts[it.key] = it.value }
    }

    fun getText(key: String) = texts[key] ?: key

    @Serializable
    data class TextValue(
        val key: String,
        val value: String
    )
}