import androidx.compose.runtime.Composable
import org.jetbrains.compose.web.css.Color
import org.jetbrains.compose.web.css.DisplayStyle
import org.jetbrains.compose.web.css.JustifyContent
import org.jetbrains.compose.web.css.backgroundColor
import org.jetbrains.compose.web.css.borderRadius
import org.jetbrains.compose.web.css.color
import org.jetbrains.compose.web.css.display
import org.jetbrains.compose.web.css.fontSize
import org.jetbrains.compose.web.css.gap
import org.jetbrains.compose.web.css.height
import org.jetbrains.compose.web.css.justifyContent
import org.jetbrains.compose.web.css.padding
import org.jetbrains.compose.web.css.percent
import org.jetbrains.compose.web.css.px
import org.jetbrains.compose.web.css.width
import org.jetbrains.compose.web.dom.Button
import org.jetbrains.compose.web.dom.Div
import org.jetbrains.compose.web.dom.Text

@Composable
fun TopButtons(viewModel: AppViewModel, onClick: () -> Unit) {
    Div(attrs = {
        style {
            display(DisplayStyle.Flex)
            property("flex-wrap", "wrap")
            justifyContent(JustifyContent.Center)
            gap(6.px)
            width(100.percent)
        }
    }) {
        viewModel.topButtons.forEach { (label, action) ->
            Button(attrs = {
                classes(GranitStyles.button)
                onClick { action(); onClick() }
                style {
                    width(106.px); height(36.px)
                    padding(6.px)
                    borderRadius(9.px)
                    backgroundColor(Color(AppColors.BUTTON_COLOR))
                    color(Color(AppColors.BUTTON_CONTENT_COLOR))
                    fontSize(12.5.px)
                }
            }) { Text(viewModel.getText(label)) }
        }
    }
}